-- =====================================================================
-- 로드맵 과제 추가(4): 남은 일 일괄 등록 T-xx 33개 (예약(월 01시) 3 · 신규 요청 1 · 보류 3 · 결정 대기 10 · 출시 전 8 · 기술부채 8) + 기존 과제 4개 현황 보정
--   * 20261115000000_roadmap_items_3.sql 이 먼저 적용돼 있어야 한다. 앞선 마이그레이션의 내용은 바꾸지 않는다.
--   * 내용의 출처: docs/ux/BACKLOG_ROADMAP_ITEMS.json (2026-11-14 사용자 지시 '지금까지 해야할 일을 모두 로드맵에 저장'), docs/BACKLOG.md
--   * 분류(category)가 표시: 예약(월 01시) · 신규 요청 · 보류 · 결정 대기 · 출시 전 · 기술부채. 보류 = 상태 'dropped'(보류·제외).
--   * 이 파일은 admin/tools_seed_roadmap.mjs 가 생성한다. 직접 고치지 말고 JSON 을 고친 뒤 다시 생성.
--   * 멱등: 시드는 on conflict do nothing. 현황 보정은 상태가 아직 'todo' 인 행·메모가 비었거나 기본 문구인 행·제목이 원래 그대로인 행에만 적용한다(관리자가 바꾼 것은 건드리지 않음).
--   * 이 저장소에서는 아직 실제 Supabase 에 적용하지 않았다.
-- =====================================================================

on conflict (id) do nothing;

-- 기존 과제 현황 보정(구현 근거가 있는 것만)
update public.roadmap_items
   set status = case when status = 'todo' then 'review' else status end,
       owner_note = case when owner_note in ('') then '2026-11-13 구현: 성당 안 14처 판·순례(SPEC 30), 기도 배경·더보기·사순 카드. 사제 검수(T-31)·실기기 확인 대기.' else owner_note end,
       updated_at = now()
 where id = 'C-12'
   and (status = 'todo' or owner_note in (''));

update public.roadmap_items
   set title = case when title = 'IA 개편: 유리화 탭(기본) 추가, 성당을 유리화 탭의 [창|성당] 보기로 합침, 탭 4개 유지' then 'IA 개편: 성당 탭(기본) + [성당|창] 보기로 갤러리(창)를 같은 탭 안에 둠, 탭 4개 유지(소유자 지시로 ''유리화'' 기본 탭에서 변경)' else title end,
       status = case when status = 'todo' then 'done' else status end,
       owner_note = case when owner_note in ('', '제안: 소유자 확인 대기') then '2026-11-13 완료: 탭 ''성당''·[성당|창]·가상 성당 헤더(커밋 e96c3fb). 제목은 현재 구조에 맞게 갱신.' else owner_note end,
       updated_at = now()
 where id = 'G-01'
   and (title = 'IA 개편: 유리화 탭(기본) 추가, 성당을 유리화 탭의 [창|성당] 보기로 합침, 탭 4개 유지' or status = 'todo' or owner_note in ('', '제안: 소유자 확인 대기'));

update public.roadmap_items
   set status = case when status = 'todo' then 'done' else status end,
       owner_note = case when owner_note in ('', '제안: 소유자 확인 대기') then '2026-11-13 완료: 성당 안 진본 스테인드글라스 연결 7점·4개 성당(커밋 859be21).' else owner_note end,
       updated_at = now()
 where id = 'G-29'
   and (status = 'todo' or owner_note in ('', '제안: 소유자 확인 대기'));

update public.roadmap_items
   set owner_note = case when owner_note in ('2차 화면 캡처 검토') then '출시 전 확인 묶음: 소리·성능·TalkBack·저사양 3D·선창 뒷단 목소리(앞단 뒤 앱이 부르는 resp 클립)도 이 검증표로 실기기 확인. 음성 클립 없는 오래된 APK 로는 검증 불가(T-36).' else owner_note end,
       updated_at = now()
 where id = 'U-33'
   and (owner_note in ('2차 화면 캡처 검토'));
